import React, { useState, useEffect } from "react";

const LOGO_URL = "data:image/png;base64,";

const palette = {
  bg: "#080604",
  panel: "#100c08",
  border: "#3a2c17",
  borderBright: "#e89a24",
  textDim: "#8a7a5c",
  textMute: "#6b5d43",
  textLight: "#e7ddca",
  textBright: "#f5efe2",
  amber: "#e89a24",
  amberSoft: "#df8a18",
  gold: "#f6c44e",
  good: "#7fae6b",
};

// Corchete decorativo tipo "mira" de instrumento, en cada esquina del panel.
// `position` decide en qué esquina va y qué rotación necesita para apuntar hacia adentro.
function Corner({ position }) {
  const map = {
    topLeft: { rotate: 0, top: 10, left: 10 },
    topRight: { rotate: 90, top: 10, right: 10 },
    bottomRight: { rotate: 180, bottom: 10, right: 10 },
    bottomLeft: { rotate: 270, bottom: 10, left: 10 },
  };
  const { rotate, ...pos } = map[position];

  return (
    <svg
      width="26"
      height="26"
      viewBox="0 0 26 26"
      style={{ position: "absolute", transform: `rotate(${rotate}deg)`, ...pos }}
    >
      <path d="M2 14 L2 2 L14 2" stroke={palette.amber} strokeWidth="2" fill="none" />
    </svg>
  );
}

export default function LoginDestilacion() {
  const [usuario, setUsuario] = useState("");
  const [contrasena, setContrasena] = useState("");
  const [focoUsuario, setFocoUsuario] = useState(false);
  const [focoPass, setFocoPass] = useState(false);
  const [hora, setHora] = useState(new Date());

  useEffect(() => {
    const id = setInterval(() => setHora(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  function login() {
    console.log("login", { usuario, contrasena });
  }

  function campoStyle(activo) {
    return {
      width: "100%",
      background: "#0d0a06",
      border: `1px solid ${activo ? palette.amber : palette.border}`,
      borderRadius: 3,
      color: palette.textBright,
      fontFamily: "'IBM Plex Mono', monospace",
      fontSize: 14,
      padding: "13px 14px",
      outline: "none",
      boxSizing: "border-box",
      transition: "border-color 0.15s ease, box-shadow 0.15s ease",
      boxShadow: activo ? `0 0 0 3px ${palette.amber}22` : "none",
    };
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        background: palette.bg,
        fontFamily: "'IBM Plex Sans', sans-serif",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        position: "relative",
        overflow: "hidden",
        padding: 20,
      }}
    >
      {/* Fondo tipo blueprint: cuadrícula técnica */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: `linear-gradient(${palette.border}22 1px, transparent 1px), linear-gradient(90deg, ${palette.border}22 1px, transparent 1px)`,
          backgroundSize: "42px 42px",
          maskImage: "radial-gradient(circle at 50% 40%, black 0%, transparent 75%)",
        }}
      />

      {/* Barra superior tipo HUD: fecha + hora */}
      <div
        style={{
          position: "absolute",
          top: 22,
          left: 0,
          right: 0,
          display: "flex",
          justifyContent: "center",
          gap: 24,
          fontFamily: "'IBM Plex Mono', monospace",
          fontSize: 11,
          color: palette.textMute,
          letterSpacing: "0.08em",
          flexWrap: "wrap",
          padding: "0 20px",
        }}
      >
        <span>
          {hora
            .toLocaleDateString("es-MX", {
              weekday: "short",
              day: "2-digit",
              month: "short",
              year: "numeric",
            })
            .toUpperCase()}
        </span>

        <span style={{ color: palette.border }}>|</span>

        <span style={{ color: palette.textLight }}>
          {hora.toLocaleTimeString("es-MX", { hour12: false })}
        </span>
      </div>

      {/* ── Panel central tipo instrumento ── */}
      <div
        style={{
          position: "relative",
          width: "100%",
          maxWidth: 400,
          background: palette.panel,
          border: `1px solid ${palette.border}`,
          borderRadius: 6,
          padding: "42px 38px 34px",
          boxShadow: "0 30px 60px -20px rgba(0,0,0,0.6)",
        }}
      >
        {/* ESQUINAS DECORATIVAS */}
        <Corner position="topLeft" />
        <Corner position="topRight" />
        <Corner position="bottomRight" />
        <Corner position="bottomLeft" />

        {/* Logo + marca */}
        <div style={{ textAlign: "center", marginBottom: 34 }}>
          <img
            src={LOGO_URL}
            alt="Logo"
            style={{
              width: 190,
              height: "auto",
              display: "block",
              margin: "0 auto",
            }}
          />

          <div
            style={{
              fontFamily: "'IBM Plex Mono', monospace",
              fontSize: 10,
              letterSpacing: "0.28em",
              color: palette.textMute,
              marginTop: 22,
            }}
          >
            MONITOREO IOT · ACCESO
          </div>

          <div
            style={{
              fontFamily: "'Playfair Display', serif",
              fontSize: 30,
              color: palette.textBright,
              fontWeight: 700,
              marginTop: 8,
            }}
          >
            DESTILACIÓN
          </div>
        </div>

        {/* Campo usuario */}
        <div style={{ marginBottom: 16 }}>
          <label
            style={{
              display: "block",
              fontFamily: "'IBM Plex Mono', monospace",
              fontSize: 10.5,
              letterSpacing: "0.08em",
              color: palette.amber,
              marginBottom: 7,
              textTransform: "uppercase",
            }}
          >
            &gt; Usuario
          </label>

          <input
            style={campoStyle(focoUsuario)}
            value={usuario}
            onChange={(e) => setUsuario(e.target.value)}
            onFocus={() => setFocoUsuario(true)}
            onBlur={() => setFocoUsuario(false)}
            onKeyDown={(e) => e.key === "Enter" && login()}
          />
        </div>

        {/* Campo contraseña */}
        <div style={{ marginBottom: 26 }}>
          <label
            style={{
              display: "block",
              fontFamily: "'IBM Plex Mono', monospace",
              fontSize: 10.5,
              letterSpacing: "0.08em",
              color: palette.amber,
              marginBottom: 7,
              textTransform: "uppercase",
            }}
          >
            &gt; Contraseña
          </label>

          <input
            type="password"
            style={campoStyle(focoPass)}
            value={contrasena}
            onChange={(e) => setContrasena(e.target.value)}
            onFocus={() => setFocoPass(true)}
            onBlur={() => setFocoPass(false)}
            onKeyDown={(e) => e.key === "Enter" && login()}
          />
        </div>

        {/* Botón iniciar sesión */}
        <button
          onClick={login}
          style={{
            width: "100%",
            padding: "14px 0",
            background: `linear-gradient(135deg, ${palette.amber}, ${palette.amberSoft})`,
            border: "none",
            borderRadius: 3,
            color: palette.bg,
            fontFamily: "'IBM Plex Mono', monospace",
            fontSize: 13,
            fontWeight: 700,
            letterSpacing: "0.14em",
            cursor: "pointer",
            textTransform: "uppercase",
          }}
        >
          Iniciar sesión
        </button>

        {/* Crear cuenta */}
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            marginTop: 20,
            fontFamily: "'IBM Plex Mono', monospace",
            fontSize: 11.5,
          }}
        >
          <button
            type="button"
            style={{
              color: palette.gold,
              textDecoration: "none",
	      background: "none",
              border: "none",
              cursor: "pointer",
              font: "inherit",
              padding: 0,
            }}
          >
            Crear cuenta
          </button>
        </div>
      </div>
    </div>
  );
}
